"""Offline human source annotation; no predictions, network, or source execution."""
from __future__ import annotations

import json

from .source_review import source_review_template


def render_source_review(packet):
    template = source_review_template(packet)
    if any(case["annotation"] is not None for case in packet["cases"]):
        raise ValueError("blind review starts from an unannotated packet")
    payload = json.dumps({"packet": packet, "review": template}, ensure_ascii=False, allow_nan=False)
    payload = payload.replace("&", "\\u0026").replace("<", "\\u003c").replace(">", "\\u003e")
    return _PAGE.replace("__PAYLOAD__", payload)


_PAGE = r'''<!doctype html>
<html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'nonce-source-review'; style-src 'unsafe-inline'; connect-src 'none'; base-uri 'none'; form-action 'none'">
<title>Parcimonia - Revue des sources</title><style>
*{box-sizing:border-box}body{margin:0;color:#20282b;background:#f5f7f8;font:14px/1.5 system-ui,sans-serif;letter-spacing:0}button,input,select,textarea{font:inherit;letter-spacing:0}button{cursor:pointer;background:white;color:#20282b;border:1px solid #b7c1c6;border-radius:4px;padding:8px 12px}button:hover{border-color:#216f54}button:disabled{opacity:.45;cursor:default}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid #216f54;outline-offset:2px}header{padding:16px 24px;background:white;border-bottom:1px solid #cfd7dc;display:flex;justify-content:space-between;align-items:center;gap:16px}h1{font-size:21px;line-height:1.3;margin:0}.actions{display:flex;flex-wrap:wrap;gap:8px}.primary{background:#216f54;border-color:#216f54;color:white}.layout{display:grid;grid-template-columns:250px minmax(0,1fr)}aside{padding:20px;border-right:1px solid #cfd7dc;background:#edf1f4;max-height:calc(100vh - 70px);position:sticky;top:0;overflow:auto}main{min-width:0;padding:24px;max-width:1300px}.progress{font-size:20px;font-weight:600;margin:0 0 14px}.case-button{display:block;text-align:left;width:100%;margin:0 0 6px;padding:10px;overflow-wrap:anywhere;font-size:12px}.case-button.active{border-left:4px solid #216f54;background:#e5f1eb}label{display:block;font-size:13px;font-weight:600;margin-bottom:5px}input,select,textarea{width:100%;min-width:0;padding:8px;border:1px solid #b7c1c6;border-radius:3px;background:white;color:#20282b}textarea{min-height:86px;resize:vertical}.identity{margin:18px 0}.muted{color:#54656e;font-size:12px;overflow-wrap:anywhere}h2{font-size:18px;margin:0 0 12px;line-height:1.4;overflow-wrap:anywhere}h3{font-size:15px;margin:0 0 10px}.band{border-top:1px solid #cfd7dc;padding-top:20px;margin-top:22px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.full{grid-column:1/-1}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.55 ui-monospace,Consolas,monospace;background:white;padding:14px;margin:10px 0;border:1px solid #d4dde2;max-height:360px;overflow:auto}details{margin:10px 0}summary{cursor:pointer;font-size:13px;font-weight:600}.candidate{border-top:1px solid #cfd7dc;padding-top:14px;margin-top:14px}.check{display:flex;gap:9px;align-items:flex-start;font-weight:400}.check input{width:18px;height:18px;flex:none}.footer{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap;margin-top:24px}.icon{width:42px;height:38px;padding:0;font-size:20px}#status{min-height:22px;margin:14px 0;color:#9c351f;overflow-wrap:anywhere}@media(max-width:800px){header{padding:16px;align-items:flex-start}.layout{grid-template-columns:200px minmax(0,1fr)}main{padding:20px}.grid{grid-template-columns:1fr}.full{grid-column:auto}}@media(max-width:580px){header{display:block}.actions{margin-top:12px}.layout{display:block}aside{position:static;max-height:none;padding:16px}#caseList{max-height:150px;overflow:auto}main{padding:16px}h1{font-size:20px}}
.candidate{overflow-wrap:anywhere}
</style></head><body><header><h1>Parcimonia / Revue des sources</h1><div class="actions"><button id="importButton">Importer</button><button id="exportButton" class="primary">Exporter la revue</button><input id="importFile" type="file" accept="application/json,.json" hidden></div></header>
<div class="layout"><aside><div class="progress" id="progress">0 / 0</div><div class="identity"><label for="reviewer">Annotateur</label><input id="reviewer" autocomplete="off"></div><label for="search">Recherche</label><input id="search" type="search"><div id="caseList" style="margin-top:16px"></div></aside>
<main><div class="muted" id="caseNumber"></div><h2 id="title"></h2><div class="muted" id="provenance"></div><pre id="sourceText"></pre>
<details><summary>Contexte du projet</summary><pre id="projectContext"></pre></details>
<section class="band"><h3>Attention</h3><div class="grid"><div><label for="attention">Traitement attendu</label><select id="attention"><option value="">A examiner</option><option value="process">Traiter</option><option value="defer">Reporter</option><option value="skip_candidate">Ecarter de la file active</option><option value="needs_context">Contexte requis</option><option value="uncertain">Non etabli</option></select></div><div><label for="mustRetain">Information a conserver dans la file</label><select id="mustRetain"><option value="">A examiner</option><option value="true">Oui</option><option value="false">Non</option><option value="unknown">Non etabli</option></select></div><div><label for="language">Langue de la source</label><select id="language"><option value="">A examiner</option><option value="fr">Francais</option><option value="en">Anglais</option><option value="mixed">Mixte</option><option value="other">Autre</option><option value="unknown">Non etablie</option></select></div><div><label for="eventGroup">Groupe d'evenement</label><input id="eventGroup" autocomplete="off"></div></div></section>
<section class="band"><h3>Relations avec les sources retrouvees</h3><div id="candidates"></div></section>
<section class="band"><h3>Justification</h3><label class="check"><input id="sourceReviewed" type="checkbox">Provenance et groupes examines</label><label for="rationale">Elements observes et incertitudes</label><textarea id="rationale"></textarea></section>
<div class="footer"><button id="previous" class="icon" title="Source precedente" aria-label="Source precedente">&larr;</button><label class="check"><input id="complete" type="checkbox">Revue terminee</label><button id="next" class="icon" title="Source suivante" aria-label="Source suivante">&rarr;</button></div><div id="status" role="status" aria-live="polite"></div></main></div>
<script type="application/json" id="payload">__PAYLOAD__</script><script nonce="source-review">
"use strict";
const payload=JSON.parse(document.getElementById('payload').textContent),packet=payload.packet,cases=packet.cases,blank=payload.review,key='parcimonia.source-review.'+packet.pack_id,$=id=>document.getElementById(id);
const relationLabels={duplicate:'Doublon',update:'Mise a jour',contradiction:'Contradiction',novel:'Information nouvelle par rapport a cette source',uncertain:'Non etabli'};
let review=JSON.parse(JSON.stringify(blank)),index=0,owner='',retainModes={};
function node(tag,text){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n}
function valid(a,c){return typeof a.reviewer_id==='string'&&a.reviewer_id.trim()&&a.source_reviewed===true&&typeof a.rationale==='string'&&a.rationale.trim()&&['fr','en','mixed','other','unknown'].includes(a.language)&&['process','defer','skip_candidate','needs_context','uncertain'].includes(a.labels.attention)&&retainModes[c.case_id]&&Object.keys(a.labels.relations).length===c.candidates.length&&c.candidates.every(s=>Object.hasOwn(relationLabels,a.labels.relations[s.id]))&&!(a.labels.attention==='skip_candidate'&&(a.labels.must_retain===true||c.source.protected===true))}
function persist(){try{localStorage.setItem(key,JSON.stringify({review,owner,retainModes}));$('status').textContent=''}catch(e){$('status').textContent='Sauvegarde navigateur indisponible.'}}
function save(force=false){if(!force){persist();drawList();return}const c=cases[index],a=review.annotations[c.case_id],wanted=$('complete').checked;a.labels.attention=$('attention').value||null;retainModes[c.case_id]=$('mustRetain').value;a.labels.must_retain=$('mustRetain').value==='true'?true:$('mustRetain').value==='false'?false:null;a.language=$('language').value||null;a.event_group=$('eventGroup').value.trim()||null;a.rationale=$('rationale').value||null;a.source_reviewed=$('sourceReviewed').checked;a.reviewer_id=owner.trim()||null;a.complete=wanted&&!!valid(a,c);$('complete').checked=a.complete;persist();if(wanted&&!a.complete)$('status').textContent='Annotations incompletes ou incoherentes.';drawList()}
function drawList(){const total=Object.values(review.annotations).filter(a=>a.complete).length;$('progress').textContent=total+' / '+cases.length;$('caseList').replaceChildren();const query=$('search').value.toLocaleLowerCase();cases.forEach((c,i)=>{if(!c.source.title.toLocaleLowerCase().includes(query)&&!c.source.text.toLocaleLowerCase().includes(query))return;const b=node('button',(i+1)+'. '+c.source.title+(review.annotations[c.case_id].complete?' [revue]':''));b.className='case-button'+(i===index?' active':'');b.onclick=()=>{save();index=i;draw()};$('caseList').append(b)})}
function draw(){const c=cases[index],a=review.annotations[c.case_id];$('caseNumber').textContent='Source '+(index+1)+' / '+cases.length;$('title').textContent=c.source.title;$('sourceText').textContent=c.source.text;$('provenance').textContent=c.source.reference+' | Capture '+c.provenance.captured_at+' | SHA-256 '+c.provenance.sha256;$('projectContext').textContent=JSON.stringify(c.context,null,2);$('attention').value=a.labels.attention||'';$('mustRetain').value=retainModes[c.case_id]||'';$('language').value=a.language||'';$('eventGroup').value=a.event_group||'';$('rationale').value=a.rationale||'';$('sourceReviewed').checked=a.source_reviewed;$('complete').checked=a.complete;$('candidates').replaceChildren();for(const s of c.candidates){const block=node('div');block.className='candidate';block.append(node('h3',s.title),node('div',s.reference));const details=node('details');details.append(node('summary','Texte capture'),node('pre',s.text));block.append(details);const label=node('label','Relation de la source courante avec ce document'),select=node('select');select.setAttribute('aria-label','Relation avec '+s.title);select.dataset.candidate=s.id;const first=node('option','A examiner');first.value='';select.append(first);for(const [value,text]of Object.entries(relationLabels)){const option=node('option',text);option.value=value;select.append(option)}select.value=a.labels.relations[s.id]||'';select.onchange=()=>{a.labels.relations[s.id]=select.value||null;save(true)};block.append(label,select);$('candidates').append(block)}$('previous').disabled=index===0;$('next').disabled=index===cases.length-1;drawList()}
function importReview(data,modes){if(data.schema!==blank.schema||data.packet_id!==packet.pack_id||typeof data.annotations!=='object'||data.annotations===null||Array.isArray(data.annotations))throw new Error('Dossier incompatible');const next=JSON.parse(JSON.stringify(blank)),nextModes={};for(const [id,a]of Object.entries(data.annotations)){const original=blank.annotations[id],c=cases.find(c=>c.case_id===id);if(!original||a.case_hash!==original.case_hash||Object.keys(a).sort().join('|')!==Object.keys(original).sort().join('|')||typeof a.labels!=='object'||a.labels===null||Object.keys(a.labels).sort().join('|')!==Object.keys(original.labels).sort().join('|'))throw new Error('Annotation incompatible');if(typeof a.complete!=='boolean'||typeof a.source_reviewed!=='boolean'||![null,true,false].includes(a.labels.must_retain)||!Object.keys(a.labels.relations).every(k=>Object.hasOwn(original.labels.relations,k))||Object.keys(a.labels.relations).length!==c.candidates.length)throw new Error('Labels incompatibles');if(a.labels.attention!==null&&!['process','defer','skip_candidate','needs_context','uncertain'].includes(a.labels.attention))throw new Error('Traitement incompatible');if(!Object.values(a.labels.relations).every(v=>v===null||Object.hasOwn(relationLabels,v)))throw new Error('Relation incompatible');next.annotations[id]=JSON.parse(JSON.stringify(a));nextModes[id]=modes?.[id]||(a.labels.must_retain===true?'true':a.labels.must_retain===false?'false':a.complete?'unknown':'')};review=next;retainModes=nextModes;for(const c of cases){const a=review.annotations[c.case_id];a.complete=a.complete&&!!valid(a,c)}}
function exportRecord(){save();return JSON.parse(JSON.stringify(review))}
try{const saved=JSON.parse(localStorage.getItem(key));if(saved){importReview(saved.review,saved.retainModes);owner=typeof saved.owner==='string'?saved.owner:''}}catch(e){}
$('reviewer').value=owner;$('reviewer').oninput=()=>{owner=$('reviewer').value;save(true)};$('search').oninput=drawList;
for(const id of ['attention','mustRetain','language','eventGroup','rationale','sourceReviewed','complete'])$(id).onchange=()=>save(true);
$('previous').onclick=()=>{save();if(index>0){index--;draw()}};$('next').onclick=()=>{save();if(index<cases.length-1){index++;draw()}};
$('exportButton').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(exportRecord(),null,2)],{type:'application/json'})),a=node('a');a.href=url;a.download='source-review-'+packet.pack_id.slice(0,12)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('importButton').onclick=()=>$('importFile').click();$('importFile').onchange=async()=>{try{importReview(JSON.parse(await $('importFile').files[0].text()));persist();draw()}catch(e){$('status').textContent='Import refuse : '+e.message}};
draw();
</script></body></html>'''
